con:config.script:
import org.apache.poi.ss.usermodel.*
import org.apache.poi.xssf.usermodel.XSSFWorkbook
import java.io.FileInputStream
import groovy.json.JsonOutput

// Adjust path to your Excel file
def filePath = 'D:/sdet-capstone/SoapUI Automation/EmployeeData.xlsx'
def fis = new FileInputStream(filePath)
def workbook = new XSSFWorkbook(fis)
def sheet = workbook.getSheetAt(0)

def testCase = context.testCase
def restTestStep = testCase.testSteps["CreateRequest"]

for (int i = 1; i <= sheet.getLastRowNum(); i++) {
    def row = sheet.getRow(i)
    def name = row.getCell(0)?.toString()
    def salary = row.getCell(1)?.toString()
    def age = row.getCell(2)?.toString()

    def payload = [
        name  : name,
        salary: salary,
        age   : age
    ]

    def jsonPayload = JsonOutput.toJson(payload)

    restTestStep.testRequest.requestContent = jsonPayload

    def response = restTestStep.testRequest.submit(new com.eviware.soapui.support.types.StringToObjectMap(), false)
    def responseContent = response.responseContent
    def statusLine = response.responseHeaders["#status#"]?.toString()

    log.info "\nPayload: ${jsonPayload}"
    log.info "Status: ${statusLine}"
    log.info "Response: ${responseContent}"

    if (name && salary && age) {
        assert responseContent.contains(name)
        assert responseContent.contains(salary)
        assert responseContent.contains(age)
        assert statusLine.contains("200") || statusLine.contains("201")
    } else {
        assert !statusLine.contains("200") : "Expected failure for missing fields"
    }
}

fis.close()
workbook.close()
